-- 展示当前服务器的所有玩家scope

local function InfoPlayerScopes(world, debugger: ITangSengDebugger, services: IServiceProvider)
	local ui = debugger:getWidgets()

	ui.window({
		title = `玩家作用域列表`,
		closable = true,
		minSize = Vector2.new(200, 10),
		maxSize = Vector2.new(300, 300),
	}, function()
		local playerScopeService = services:GetRequiredService("IPlayerScopeService")
		local scopeCache = playerScopeService._innerGetCache()
		for playerId, scope in scopeCache do
			-- userid,serviceCount
			ui.label(`{playerId},{scope._serviceProvider._newCacheCount}`)
		end
	end)
end

return InfoPlayerScopes
